package orchestrator

import (
	"encoding/json"
	"testing"

	"github.com/google/uuid"
	"github.com/godinj/drem-orchestrator/internal/model"
	"github.com/godinj/drem-orchestrator/internal/testutil"
	"github.com/godinj/drem-orchestrator/internal/worktree"
)

func TestReconcileFailedParents_ConstraintGateExhausted_NoNewCommits(t *testing.T) {
	orch, db, bareRepo := setupReconcileTest(t)
	defer bareRepo.Close()

	featureName := "feature-exhausted"
	featureDir, err := testutil.CreateFeatureWorktree(t, bareRepo, featureName)
	if err != nil {
		t.Fatalf("failed to create feature worktree: %v", err)
	}
	defer testutil.RemoveDir(t, featureDir)

	// Get HEAD SHA
	out, err := worktree.RunGit(featureDir, "rev-parse", "HEAD")
	if err != nil {
		t.Fatalf("failed to get HEAD SHA: %v", err)
	}
	headSHA := string(out)

	parentID := uuid.New()
	parent := model.Task{
		ID:             parentID,
		ProjectID:      orch.projectID,
		Title:          "failed-parent-exhausted",
		Status:         model.StatusFailed,
		WorktreeBranch: "refs/heads/" + featureName,
		Context: map[string]string{
			"constraint_gate_exhausted":        "true",
			"constraint_gate_failed_at_commit": headSHA,
		},
	}
	db.Create(&parent)

	// Create all subtasks as DONE
	for i := 0; i < 2; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}

	if n != 0 {
		t.Errorf("expected 0 parents recovered, got %d", n)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status != model.StatusFailed {
		t.Errorf("expected parent to remain FAILED, got %s", updated.Status)
	}
}

func TestReconcileFailedParents_ConstraintGateExhausted_NewCommit(t *testing.T) {
	orch, db, bareRepo := setupReconcileTest(t)
	defer bareRepo.Close()

	featureName := "feature-new-commit"
	featureDir, err := testutil.CreateFeatureWorktree(t, bareRepo, featureName)
	if err != nil {
		t.Fatalf("failed to create feature worktree: %v", err)
	}
	defer testutil.RemoveDir(t, featureDir)

	// Get initial HEAD SHA
	out, err := worktree.RunGit(featureDir, "rev-parse", "HEAD")
	if err != nil {
		t.Fatalf("failed to get HEAD SHA: %v", err)
	}
	oldSHA := string(out)

	parentID := uuid.New()
	parent := model.Task{
		ID:             parentID,
		ProjectID:      orch.projectID,
		Title:          "failed-parent-exhausted-new-commit",
		Status:         model.StatusFailed,
		WorktreeBranch: "refs/heads/" + featureName,
		Context: map[string]string{
			"constraint_gate_exhausted":        "true",
			"constraint_gate_failed_at_commit": oldSHA,
		},
	}
	db.Create(&parent)

	// Create all subtasks as DONE
	for i := 0; i < 2; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	// Add a new commit to the feature worktree
	err = testutil.CommitFile(t, featureDir, "newfile.txt", "new content")
	if err != nil {
		t.Fatalf("failed to commit new file: %v", err)
	}

	// Verify SHA changed
	out, err = worktree.RunGit(featureDir, "rev-parse", "HEAD")
	if err != nil {
		t.Fatalf("failed to get new HEAD SHA: %v", err)
	}
	newSHA := string(out)
	if oldSHA == newSHA {
		t.Fatalf("expected SHA to change, but it remained %s", oldSHA)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}

	if n != 1 {
		t.Errorf("expected 1 parent recovered, got %d", n)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("expected parent to be recovered, but still %s", updated.Status)
	}

	// Assert context is cleared
	if updated.Context["constraint_gate_exhausted"] != "" {
		t.Errorf("expected constraint_gate_exhausted to be cleared, got %s", updated.Context["constraint_gate_exhausted"])
	}
	if updated.Context["constraint_gate_failed_at_commit"] != "" {
		t.Errorf("expected constraint_gate_failed_at_commit to be cleared, got %s", updated.Context["constraint_gate_failed_at_commit"])
	}
}

func TestReconcileFailedParents_NonConstraintFailure_StillRecovers(t *testing.T) {
	orch, db, _ := setupReconcileTest(t)

	parentID := uuid.New()
	parent := model.Task{
		ID:          parentID,
		ProjectID:   orch.projectID,
		Title:       "failed-parent-non-constraint",
		Status:      model.StatusFailed,
		Context:     map[string]string{"failure_reason": "merge conflict"},
	}
	db.Create(&parent)

	// Create all subtasks as DONE
	for i := 0; i < 2; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}

	if n != 1 {
		t.Errorf("expected 1 parent recovered, got %d", n)
	}

	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("expected parent to be recovered, but still %s", updated.Status)
	}
}
EOF
"}

